SELECT COALESCE(SUM(current_revision), 0) FROM learning_event_origins
WHERE user_id = #{userId} AND course_id = #{courseId} AND origin_kind IN
#{k}

SELECT execution_record_id AS id, user_id FROM execution_records
WHERE execution_record_id > #{afterId} AND created_at < #{before}
  AND (#{onlyUser} IS NULL OR user_id = #{onlyUser})
ORDER BY execution_record_id LIMIT #{limit}

SELECT course_id AS id, MIN(user_id) AS user_id FROM user_contexts
WHERE course_id > #{afterId} AND created_at < #{before}
  AND (#{onlyUser} IS NULL OR user_id = #{onlyUser})
  AND (fact_kind IN ('PROGRESS', 'EXAM_SCOPE', 'DIFFICULTY', 'RESOLVED') OR source_type = 'SELF_CHECK')
GROUP BY course_id ORDER BY course_id LIMIT #{limit}

SELECT course_id AS id, MIN(user_id) AS user_id FROM (
    SELECT course_id, user_id FROM course_scope_exclusions WHERE course_id > #{afterId} AND created_at < #{before}
    UNION ALL
    SELECT course_id, user_id FROM topic_class_progress WHERE course_id > #{afterId} AND created_at < #{before}
) c WHERE (#{onlyUser} IS NULL OR user_id = #{onlyUser}) GROUP BY course_id ORDER BY course_id LIMIT #{limit}

SELECT link_id AS id, user_id FROM material_links
WHERE link_id > #{afterId} AND linked_at < #{before}
  AND (#{onlyUser} IS NULL OR user_id = #{onlyUser})
ORDER BY link_id LIMIT #{limit}
